class TestAggregateO2mColumnAction(BloomerpBehaviorActionTestCase):
    """Cover all exposed aggregate operations and authorization boundaries."""

    action = AGGREGATE_O2M_COLUMN
    auto_create_customers = False
    invoice_model: type[models.Model]
    line_model: type[models.Model]

    @classmethod
    def setUpClass(cls) -> None:
        """Create numeric collection sources and top-level aggregate targets."""
        super().setUpClass()
        fixtures = create_test_models(
            "bloomerp",
            {
                "AggregateInvoice": {
                    "name": models.CharField(max_length=40),
                    "total": models.DecimalField(
                        max_digits=10, decimal_places=2, null=True, blank=True
                    ),
                    "item_count": models.IntegerField(null=True, blank=True),
                },
                "AggregateInvoiceLine": {
                    "invoice": models.ForeignKey(
                        "bloomerp.AggregateInvoice",
                        on_delete=models.CASCADE,
                        related_name="lines",
                    ),
                    "amount": models.DecimalField(
                        max_digits=10, decimal_places=2, null=True, blank=True
                    ),
                    "quantity": models.IntegerField(null=True, blank=True),
                },
            },
            use_bloomerp_base=True,
        )
        cls.invoice_model = fixtures["AggregateInvoice"]
        cls.line_model = fixtures["AggregateInvoiceLine"]

    def _field(self, name: str, *, child: bool = False) -> ApplicationField:
        """Resolve a parent or child ApplicationField from the aggregate fixture."""
        model = self.line_model if child else self.invoice_model
        return self.get_application_field(name, model)

    def _scenario(
        self,
        name: str,
        operation: str,
        rows: list[dict[str, object]],
        expected: object,
        *,
        target_name: str = "total",
        column_name: str = "amount",
        target_value: object = None,
        write_policy: str | None = None,
        should_update: bool = True,
    ) -> BehaviorActionScenario:
        """Build an exact action scenario for one aggregate operation."""
        config = {"aggregation_type": operation, "column": column_name}
        if write_policy is not None:
            config["write_policy"] = write_policy
        return BehaviorActionScenario(
            name=name,
            context=BehaviorContext(
                values={"lines": rows, target_name: target_value},
                listener_field="lines",
                target_field=target_name,
            ),
            listener=self._field("lines"),
            target=self._field(target_name),
            config=config,
            expected_result=(
                BehaviorResult(
                    values=(
                        FieldValueUpdate(
                            field=target_name,
                            value=expected,
                        ),
                    )
                )
                if should_update
                else BehaviorResult()
            ),
        )

    def get_test_scenarios(self) -> list[BehaviorActionScenario]:
        """Cover sum, count, first, last, blanks, deletion, empty input, and errors."""
        rows = [
            {"id": "line-1", "amount": Decimal("0.10"), "quantity": 1},
            {"id": "line-2", "amount": None, "quantity": None},
            {"id": "line-3", "amount": Decimal("0.20"), "quantity": 2},
            {"id": "line-4", "amount": Decimal("9.00"), "DELETE": True},
        ]
        scenarios = [
            self._scenario(
                "Sum uses exact decimals and ignores blank and deleted rows",
                "sum",
                rows,
                Decimal("0.30"),
            ),
            self._scenario(
                "Count includes only nonblank active column values",
                "count",
                rows,
                2,
                target_name="item_count",
            ),
            self._scenario(
                "First returns the first nonblank active value",
                "first",
                rows,
                Decimal("0.10"),
            ),
            self._scenario(
                "Last returns the last nonblank active value",
                "last",
                rows,
                Decimal("0.20"),
            ),
            self._scenario(
                "An empty collection sums to zero",
                "sum",
                [],
                Decimal("0.00"),
            ),
            self._scenario(
                "All-deleted rows produce an empty first result",
                "first",
                [{"amount": Decimal("4.00"), "DELETE": True}],
                None,
            ),
            self._scenario(
                "Explicit always overwrites a nonzero target",
                "sum",
                [{"amount": Decimal("2.00")}],
                Decimal("2.00"),
                target_value=Decimal("9.00"),
                write_policy="always",
            ),
            self._scenario(
                "An omitted legacy policy still overwrites a nonzero target",
                "sum",
                [{"amount": Decimal("3.00")}],
                Decimal("3.00"),
                target_value=Decimal("9.00"),
            ),
            self._scenario(
                "Empty-only writes an absent target",
                "sum",
                [{"amount": Decimal("4.00")}],
                Decimal("4.00"),
                target_value=None,
                write_policy="if_empty",
            ),
            self._scenario(
                "Empty-only preserves Decimal zero",
                "sum",
                [{"amount": Decimal("5.00")}],
                Decimal("5.00"),
                target_value=Decimal("0.00"),
                write_policy="if_empty",
                should_update=False,
            ),
            self._scenario(
                "Empty-or-zero writes a normalized string zero",
                "sum",
                [{"amount": Decimal("6.00")}],
                Decimal("6.00"),
                target_value="0.00",
                write_policy="if_empty_or_zero",
            ),
            self._scenario(
                "Empty-or-zero writes a blank target",
                "sum",
                [{"amount": Decimal("6.50")}],
                Decimal("6.50"),
                target_value="",
                write_policy="if_empty_or_zero",
            ),
            self._scenario(
                "Empty-or-zero writes a Decimal zero",
                "sum",
                [{"amount": Decimal("7.00")}],
                Decimal("7.00"),
                target_value=Decimal(0),
                write_policy="if_empty_or_zero",
            ),
            self._scenario(
                "Empty-or-zero preserves a nonzero target without an update",
                "sum",
                [{"amount": Decimal("8.00")}],
                Decimal("8.00"),
                target_value="1.50",
                write_policy="if_empty_or_zero",
                should_update=False,
            ),
        ]
        invalid = BehaviorActionScenario(
            name="Invalid numeric source values are rejected",
            context=BehaviorContext(
                values={"lines": [{"amount": "not-a-number"}], "total": None},
                listener_field="lines",
                target_field="total",
            ),
            listener=self._field("lines"),
            target=self._field("total"),
            config={"aggregation_type": "sum", "column": "amount"},
            expected_exception=ExpectedBehaviorActionException(
                ValidationError, "does not contain a numeric value"
            ),
        )
        return [*scenarios, invalid]

    def _execution_owner(
        self,
        target_field: str = "total",
    ) -> UserObjectLayoutPreference:
        """Store an aggregate action on a real invoice layout."""
        return UserObjectLayoutPreference.objects.create(
            user=self.admin_user,
            name="Aggregate invoice",
            content_type=ContentType.objects.get_for_model(self.invoice_model),
            layout=FieldLayout(
                rows=[
                    LayoutRow(
                        columns=3,
                        items=[
                            LayoutItem(id="name"),
                            LayoutItem(
                                id="lines",
                                config={
                                    "inline_fields": ["amount", "quantity"],
                                    "behaviors": BehaviorConfig(
                                        behaviors=[
                                            FormBehavior(
                                                id="aggregate-total",
                                                actions=[
                                                    BehaviorAction(
                                                        action="aggregate_o2m_column",
                                                        target_field=target_field,
                                                        config={
                                                            "aggregation_type": "sum",
                                                            "column": "amount",
                                                        },
                                                    )
                                                ],
                                            )
                                        ]
                                    ).to_storage(),
                                },
                            ),
                            LayoutItem(id=target_field),
                        ],
                    )
                ]
            ).model_dump(mode="json"),
        )

    def test_cleaned_config_contains_only_persisted_aggregate_choices(self) -> None:
        """Top-level target metadata stays in the declared action boundary."""
        cleaned = clean_action_config(
            self.action,
            self._field("lines"),
            self._field("total"),
            {"aggregation_type": "sum", "column": "amount"},
        )
        self.assertEqual(set(cleaned), {"aggregation_type", "column", "write_policy"})
        self.assertEqual(cleaned["column"].field, "amount")
        self.assertEqual(cleaned["write_policy"], "always")
        form_class = self.action.config_form_factory(
            self._field("total"), self._field("lines")
        )
        self.assertIsInstance(form_class.base_fields["write_policy"], WritePolicyField)

    def _executor(self, target_field: str = "total") -> BehaviorExecutor:
        """Create an authorized executor around one persisted invoice."""
        invoice = self.invoice_model.objects.create(name="Stored", total=0)
        return BehaviorExecutor(
            self._execution_owner(target_field), self.admin_user, instance=invoice
        )

    def test_execution_does_not_apply_child_field_permissions_to_draft_rows(
        self,
    ) -> None:
        """Draft-only aggregation does not treat supplied row values as a server read."""
        executor = self._executor()
        with patch.object(
            executor.manager,
            "has_field_permission",
            return_value=False,
        ) as permission_check:
            result = executor.evaluate(
                "lines",
                {
                    "name": "Draft",
                    "lines": [{"amount": "2.00"}],
                    "total": "0.00",
                },
            )
        permission_check.assert_not_called()
        self.assertEqual(result.values[0].value, "2.00")

    def test_execution_requires_target_to_belong_to_layout(self) -> None:
        """The top-level aggregate target remains inside the layout boundary."""
        executor = self._executor()
        executor.fields.pop("total")
        with self.assertRaises(PermissionDenied):
            executor.evaluate(
                "lines",
                {
                    "name": "Draft",
                    "lines": [{"amount": "2.00"}],
                    "total": "0.00",
                },
            )

    def test_execution_validates_natural_result_through_target_contract(self) -> None:
        """A fractional sum is rejected by a declared integer target."""
        executor = self._executor("item_count")
        with self.assertRaises(ValidationError):
            executor.evaluate(
                "lines",
                {
                    "name": "Draft",
                    "lines": [{"amount": "0.50"}],
                    "item_count": "0",
                },
            )
